const media = $json;
const context = $('Choose WordPress Create or Update').first().json;
if (!media?.id || !media?.source_url) throw new Error('WordPress did not return a media attachment ID and URL for the campaign image.');
const escapeHtml = (value) => String(value || '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
let html = String(context.content || '');
const faqMatch = html.match(/<section[^>]*class=["'][^"']*\baac-article-faq\b[^"']*["'][^>]*>[\s\S]*?<\/section>/i);
const faqHtml = faqMatch?.[0] || '';
if (faqHtml) html = html.replace(faqHtml, '').trim();
const bioMatch = html.match(/<!-- AAC_AUTHOR_BIO_START -->([\s\S]*?)<!-- AAC_AUTHOR_BIO_END -->/i);
let authorBioHtml = bioMatch?.[1]?.trim() || '';
if (authorBioHtml) {
  authorBioHtml = authorBioHtml
    .replace(/^<section\b[^>]*>/i, '<section class="aac-author-bio-card" style="display:flex;flex-wrap:wrap;align-items:center;gap:1.5rem;max-width:960px;margin:2rem auto 0;padding:1.5rem;background-color:#f4f4f4;border-radius:8px">')
    .replace('<div class="wp-block-column" style="flex-basis:144px">', '<div class="aac-author-photo-column" style="flex:0 0 144px;width:144px;max-width:144px">')
    .replace('<figure class="wp-block-image size-thumbnail is-style-rounded aac-author-photo" style="margin:0">', '<figure class="aac-author-photo" style="width:144px;height:144px;margin:0;overflow:hidden;border-radius:50%">')
    .replace(/<img src="([^"]+)" alt="([^"]+)" width="144" height="144"[^>]*>/i, '<img src="$1" alt="$2" width="144" height="144" loading="lazy" decoding="async" style="display:block;width:144px !important;height:144px !important;max-width:144px !important;object-fit:cover;border-radius:50% !important">')
    .replace('<div class="wp-block-column">', '<div class="aac-author-bio-copy" style="flex:1 1 400px;min-width:0">');
}
if (bioMatch) html = html.replace(bioMatch[0], '').trim();
html = html
  .replace(/<figure\b(?=[^>]*class=["'][^"']*\baac-featured-image\b[^"']*["'])[^>]*>[\s\S]*?<\/figure>/gi, '')
  .replace(/<section\b(?=[^>]*class=["'][^"']*\baac-author-bio\b[^"']*["'])[^>]*>[\s\S]*?<\/section>/gi, '')
  .trim();
const bylineMatch = html.match(/<!-- AAC_AUTHOR_BYLINE_START -->([\s\S]*?)<!-- AAC_AUTHOR_BYLINE_END -->/i);
const bylineHtml = bylineMatch?.[1]?.trim() || '';
if (bylineMatch) html = html.replace(bylineMatch[0], '').trim();
html = html.replace(/<!-- AAC_AUTHOR_(?:BYLINE|BIO)_(?:START|END) -->/gi, '').trim();
const byline = bylineHtml ? '<div class="aac-article-byline" style="text-align:center;font-weight:600;margin:0 0 1.25rem">' + bylineHtml + '</div>' : '';
const leadImage = '<figure class="wp-block-image size-large aac-article-lead-image" style="display:block;width:100%;max-width:680px !important;margin:0 auto 2.5rem !important;text-align:center"><div style="display:block;width:100%;max-width:680px !important;aspect-ratio:16/9;overflow:hidden;border-radius:12px"><img src="' + escapeHtml(media.source_url) + '" alt="' + escapeHtml(context.featured_image_alt_text) + '" loading="eager" decoding="async" style="display:block;width:100% !important;max-width:100% !important;height:100% !important;max-height:383px !important;object-fit:cover;border-radius:12px"></div></figure>';
const lead = '<div class="aac-article-lead" style="max-width:960px;margin:0 auto 2rem">' + byline + leadImage + '</div>';
const titleAndResponsiveStyles = '<style id="aac-article-layout-styles">body.single-post h1.entry-title,body.single-post .page-header h1,body.single-post .wp-block-post-title,body.single-post main h1:first-of-type{box-sizing:border-box;width:100%;max-width:960px;margin-left:auto!important;margin-right:auto!important;text-align:center!important}@media(min-width:1424px){.aac-article-layout.has-faq{display:grid!important;grid-template-columns:300px minmax(0,1fr) 300px!important;align-items:start!important;gap:2.5rem!important;position:relative;left:50%;transform:translateX(-50%);width:min(calc(100vw - 80px),1480px)!important;max-width:1480px!important;margin:0 auto!important;padding:0!important;box-sizing:border-box}.aac-article-layout.has-faq::before{content:"";display:block;min-width:0}.aac-article-layout.has-faq .aac-article-main,.aac-article-layout.has-faq .aac-article-sidebar{width:auto!important;max-width:none!important;min-width:0!important;margin:0!important}}@media(max-width:1423px){.aac-article-layout{display:flex!important;flex-direction:column!important;position:static!important;left:auto!important;transform:none!important;width:100%!important;max-width:1200px!important;margin:0 auto!important;padding:0 1rem!important;box-sizing:border-box}.aac-article-layout.has-faq::before{display:none!important}.aac-article-main{width:100%!important;max-width:800px!important;min-width:0!important;margin:0 auto 1.5rem!important}.aac-article-sidebar{order:2;width:100%!important;max-width:800px!important;min-width:0!important;margin:0 auto 1.5rem!important}}</style>';
const articleMain = '<div class="aac-article-main" style="min-width:0;box-sizing:border-box">' + html + '</div>';
const faqSidebar = faqHtml
  ? '<aside class="aac-article-sidebar" style="width:auto;max-width:none;min-width:0;box-sizing:border-box"><div style="padding:1.25rem;background-color:#f3f4f6;border-top:3px solid #ad0052;border-radius:4px">' + faqHtml + '</div></aside>'
  : '';
const articleLayoutClass = faqHtml ? 'aac-article-layout has-faq' : 'aac-article-layout';
const articleLayoutColumns = faqHtml ? '300px minmax(0,1fr) 300px' : 'minmax(0,1fr)';
const content = titleAndResponsiveStyles + lead + '<div class="' + articleLayoutClass + '" style="display:grid;grid-template-columns:' + articleLayoutColumns + ';align-items:start;gap:2.5rem;width:100%;max-width:1200px;margin:0 auto;padding:0 1rem;box-sizing:border-box">' + articleMain + faqSidebar + '</div>' + (authorBioHtml ? '\n' + authorBioHtml : '');
return [{ json: { ...context, content, featured_media_id: String(media.id), wordpress_body: { ...context.wordpress_body, content, featured_media: Number(media.id) } } }];

const row = $json;

if (!row.article_id) {
  throw new Error('No approved article has a complete WordPress practice configuration.');
}
if (String(row.publisher_type || '').toUpperCase() !== 'WORDPRESS') {
  throw new Error('The selected practice is not configured for the WordPress adapter.');
}

let config = {};
try {
  config = JSON.parse(row.publisher_config_reference);
} catch {
  config = { credential_name: row.publisher_config_reference };
}
if (!config.credential_name) {
  throw new Error('publisher_config_reference must name the n8n WordPress credential or contain JSON with credential_name.');
}

let publicationPackage;
try {
  publicationPackage = typeof row.publication_package_json === 'string'
    ? JSON.parse(row.publication_package_json)
    : row.publication_package_json;
} catch (error) {
  throw new Error('The approved publication package is not valid JSON: ' + error.message);
}

const metadata = publicationPackage?.metadata || {};
let html = String(publicationPackage?.article_html || '');
if (!html || !/<h1(?:\s|>)/i.test(html)) {
  throw new Error('The approved package does not contain publishable article HTML.');
}
if (/<(?:script|style|html|head|body)(?:\s|>)/i.test(html)) {
  throw new Error('The approved article contains a forbidden document or executable tag.');
}

const requireHttpsUrl = (value, label) => {
  const raw = String(value || '').trim();
  const candidate = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = /^https:\/\/([A-Za-z0-9.-]+)(\/[A-Za-z0-9._~%!$&'()*+,;=:@-]*)?\/?$/.exec(candidate);
  const host = match?.[1] || '';
  if (!match || !host.includes('.') || host.split('.').some(part => !part || part.startsWith('-') || part.endsWith('-')) || /(^|\.)example\.com$/i.test(host)) {
    throw new Error(label + ' must be an explicitly configured real HTTPS URL without credentials, query, or fragment.');
  }
  return candidate.replace(/\/+$/, '');
};
const publicUrl = requireHttpsUrl(row.website_domain, 'Public static website');
if (!config.wordpress_base_url) {
  throw new Error('WordPress multisite subsite base URL must be configured separately from the public static website.');
}
const wordpressBaseUrl = requireHttpsUrl(config.wordpress_base_url, 'WordPress subsite base');
const mappingStatus = String(config.mapping_status || '').toUpperCase();
const isTestPractice = row.practice_id === 'practice_test_001';
if (isTestPractice && wordpressBaseUrl !== 'https://apexparent.hostmanpowered.com/test001') {
  throw new Error('The TEST001 practice must use its verified test publishing base.');
}
if (!isTestPractice && mappingStatus !== 'VERIFIED') {
  throw new Error('Automatic publication requires a VERIFIED practice-to-WordPress mapping.');
}
const pilotCampaign = 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
const isPrestonwoodPilot = row.campaign_id === pilotCampaign;
if (isPrestonwoodPilot && String(row.doctor_email || '').toLowerCase() !== 'jdold@apexdp.com') {
  throw new Error('The Prestonwood pilot permits only the named test identity.');
}
const publicationBaseUrl = isPrestonwoodPilot ? 'https://apexparent.hostmanpowered.com/dfw-03' : wordpressBaseUrl;
const appointmentUrl = isPrestonwoodPilot ? 'https://prestonwooddentistry.com' : String(config.appointment_url || publicUrl);
const replacements = {
  '{{DOCTOR_NAME}}': row.doctor_name || '',
  '{{DOCTOR_CREDENTIALS}}': row.credentials || '',
  '{{PRACTICE_NAME}}': '[sc name="practice_name"][/sc]',
  '{{APPOINTMENT_URL}}': appointmentUrl
};
for (const [token, value] of Object.entries(replacements)) {
  html = html.split(token).join(String(value));
}
if (/{{[A-Z0-9_]+}}/.test(html)) {
  throw new Error('The article still contains unresolved publishing tokens.');
}

const escapeHtml = (value) => String(value || '').replace(/[&<>\"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;'
}[character]));
const featuredImageUrl = String(row.featured_image_source_url || '').trim();
const featuredImageAlt = String(row.featured_image_alt_text || '').trim();
let parsedFeaturedImageUrl;
parsedFeaturedImageUrl = featuredImageUrl;
if (!/^https:\/\/apexparent\.hostmanpowered\.com\/wp-content\/uploads\/[-A-Za-z0-9._~%/]+$/i.test(parsedFeaturedImageUrl)) {
  throw new Error('The campaign topic is missing a valid Apex Parent featured image URL.');
}
if (featuredImageAlt.length < 8) throw new Error('The campaign topic is missing useful featured image alt text.');

const doctorName = String(row.doctor_name || '').trim();
const authorBio = String(publicationPackage.author_bio || '').trim();
let authorPhotoUrl = '';
try {
  const photoUrl = String(row.photo_source_url || '').trim();
  if (/^https:\/\/[A-Za-z0-9.-]+\/[-A-Za-z0-9._~%/]+$/i.test(photoUrl)) authorPhotoUrl = photoUrl;
} catch {
  authorPhotoUrl = '';
}
let profileUrl = '';
try {
  const profileUrlCandidate = requireHttpsUrl(row.profile_url, 'Doctor profile');
  profileUrl = profileUrlCandidate;
} catch {
  profileUrl = '';}
const doctorImage = authorPhotoUrl
  ? '<figure class="wp-block-image size-thumbnail is-style-rounded aac-author-photo" style="margin:0"><img src="' + escapeHtml(authorPhotoUrl) + '" alt="Portrait of ' + escapeHtml(doctorName) + '" width="144" height="144" loading="lazy" decoding="async" style="width:144px;height:144px;object-fit:cover;border-radius:50%"></figure>'
  : '';
const authorSection = '<!-- AAC_AUTHOR_BIO_START -->\n<section class="wp-block-columns aac-author-bio" style="align-items:center;gap:1.5rem;padding:1.5rem;background-color:#f4f4f4;border-radius:8px">'
  + (doctorImage ? '<div class="wp-block-column" style="flex-basis:144px">' + doctorImage + '</div>' : '')
  + '<div class="wp-block-column"><h2>About ' + escapeHtml(doctorName || 'the author') + '</h2>'
  + (authorBio ? '<p>' + escapeHtml(authorBio) + '</p>' : '')
  + (profileUrl ? '<p><a href="' + escapeHtml(profileUrl) + '">Learn more about ' + escapeHtml(doctorName || 'the author') + '</a></p>' : '')
  + '</div></section>\n<!-- AAC_AUTHOR_BIO_END -->';
html = html
  .replace(/^(?:\s*<!--[\s\S]*?-->\s*)+/, '')
  .replace(/\s*<h1[^>]*>[\s\S]*?<\/h1>\s*/i, '\n');
const authorBioPattern = /<!-- AAC_AUTHOR_BIO_START -->[\s\S]*?<!-- AAC_AUTHOR_BIO_END -->/i;
if (authorBioPattern.test(html)) html = html.replace(authorBioPattern, authorSection);
else html = html.trim() + '\n\n' + authorSection;
html = html.replace(/<!-- AAC_AUTHOR_(?:BYLINE|BIO)_(?:START|END) -->/gi, '');

const wordpressPublishDate = String(row.wordpress_publish_date || '').trim();
if (wordpressPublishDate) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(wordpressPublishDate)) throw new Error('The campaign topic WordPress publish date is invalid.');
  const parsedDate = new Date(wordpressPublishDate + 'T00:00:00Z');
  if (!Number.isFinite(parsedDate.getTime()) || parsedDate.toISOString().slice(0, 10) !== wordpressPublishDate) throw new Error('The campaign topic WordPress publish date is not a valid calendar date.');
  if (wordpressPublishDate > new Date().toISOString().slice(0, 10)) throw new Error('The WordPress publish date cannot be in the future.');
}


const title = String(metadata.h1 || '').trim() || String(publicationPackage.article_html).match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1]?.replace(/<[^>]+>/g, '').trim();const articleSlugBase = String(metadata.slug || '').trim();
const articleIdSlug = String(row.article_id || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const articleSlugCollision = articleSlugBase.slice(0, 140) + '-article-' + articleIdSlug;
let slug = articleSlugBase;
const priorWordPressUrl = String(row.prior_wordpress_url || '').trim();
if (row.prior_wordpress_post_id && priorWordPressUrl) {
  try {
    const priorSlug = decodeURIComponent(new URL(priorWordPressUrl).pathname.split('/').filter(Boolean).at(-1) || '');
    if (/^[a-z0-9][a-z0-9-]*$/i.test(priorSlug)) slug = priorSlug;
  } catch { /* Keep the generated slug if the saved WordPress URL cannot be read. */ }
}
const excerpt = String(metadata.meta_description || '').trim();
if (!title || !slug || !excerpt) {
  throw new Error('The approved package is missing its title, slug, or meta description.');
}


return [{ json: {
  ...row,
  credential_name: config.credential_name,
  wordpress_api_url: publicationBaseUrl + '/wp-json/wp/v2',
  title, slug, article_slug_base: articleSlugBase, article_slug_collision: articleSlugCollision, excerpt, content: html,
  featured_image_source_url: featuredImageUrl,
  featured_image_alt_text: featuredImageAlt,
  wordpress_publish_date: wordpressPublishDate || null,
  wordpress_body: {
    title, content: html, slug, excerpt, status: 'publish',
    comment_status: 'closed', ping_status: 'closed', format: 'standard', ...(row.practice_id === 'practice_co_04' ? { categories: [16] } : {}),
    ...(wordpressPublishDate ? { date: wordpressPublishDate + 'T12:00:00' } : {})
  }
} }];

const context = $('Prepare WordPress Publication').first().json;
const posts = $input.all().map((item) => item.json).filter((post) => post?.id && post?.slug);
const priorPostId = String(context.prior_wordpress_post_id || '');
const priorPost = priorPostId ? posts.find((post) => String(post.id) === priorPostId) : null;
const articleSpecificPost = posts.find((post) => post.slug === context.article_slug_collision);
const baseSlugPost = posts.find((post) => post.slug === context.article_slug_base);
let slug = priorPost?.slug || context.slug;
let existingPostId = priorPost?.id ? String(priorPost.id) : null;
if (!existingPostId && articleSpecificPost) {
  slug = context.article_slug_collision;
  existingPostId = String(articleSpecificPost.id);
} else if (!existingPostId && baseSlugPost) {
  slug = context.article_slug_collision;
}
const wordpressBody = { ...context.wordpress_body, slug };
return [{ json: {
  ...context,
  slug,
  wordpress_body: wordpressBody,
  existing_post_id: existingPostId,
  wordpress_publish_url: existingPostId
    ? context.wordpress_api_url + '/posts/' + existingPostId
    : context.wordpress_api_url + '/posts'
} }];

const response = $json;
const context = $('Choose WordPress Create or Update').first().json;
if (!response?.id || response?.status !== 'publish' || !response?.link || !response?.featured_media) {
  throw new Error('WordPress did not return a published post ID, featured image, and URL.');
}
return [{ json: {
  article_id: context.article_id,
  doctor_id: context.doctor_id,
  campaign_id: context.campaign_id,
  current_version: Number(context.current_version),
  publisher_config_reference: context.publisher_config_reference,
  external_post_id: String(response.id),
  featured_media_id: String(response.featured_media),
  published_url: String(response.link),
  wordpress_status: response.status,
  slug: response.slug || context.slug
} }];
